const scope={insulation:L('Kết quả là ảnh chụp tính toán lúc lưu, gồm cả mục đạt và chưa đạt. Không cộng nhiệt trao đổi giữa các mục có thể trùng đoạn. Kiểm tra catalogue, lớp cản hơi, mối nối và cầu nhiệt trước khi áp dụng.','Results are snapshots at saving time, including passing and failing checks. Heat transfer is not summed because entries may represent the same section. Verify data sheets, vapour barriers, joints and thermal bridges before use.'),grille:L('Mỗi dòng là một nhóm miệng gió giống nhau. v = Q/(3600 × số lượng × diện tích hữu dụng). Lưu lượng tổng nhóm = lưu lượng mỗi miệng × số lượng. Đạt chỉ xác nhận giới hạn vận tốc tại diện tích hữu dụng; kiểm tra thêm độ ồn, tầm thổi và tổn thất theo catalogue.','Each row is a group of identical grilles. v = Q/(3600 × quantity × free area). Group flow = flow per grille × quantity. Pass confirms only velocity at the free area; also check sound, throw and pressure loss against catalogue data.'),fittings:L('Δp = số lượng × K × ρv²/2. Chỉ cộng các phụ kiện nối tiếp trên cùng một đường dòng; không cộng các nhánh song song. Tuyến gió và nước được tách riêng dù trùng tên. Tổng chỉ gồm phụ kiện đã lưu, chưa gồm ống thẳng, thiết bị hoặc dự phòng; không phải áp suất chọn quạt/bơm. K và nguồn do người dùng cung cấp, chưa được thẩm tra.','Δp = quantity × K × ρv²/2. Sum only consecutive fittings along one flow path; do not sum parallel branches. Air and water paths remain separate even when names match. Totals include saved fittings only, excluding straight pipes, equipment and allowance; they are not fan/pump duty pressures. K and its source are user-provided and have not been verified.')};
function conditions(items){if(items[0]?.tool==='insulation')return insulationConditions(items);return '<h3>'+L('Điều kiện tính đã lưu','Saved calculation conditions')+'</h3>'+items.map(v=>'<p><strong>'+E(v.name)+'</strong> · '+E(new Date(v.date).toLocaleString(en?'en-GB':'vi-VN',{timeZone:'Asia/Ho_Chi_Minh'}))+' · UTC+7<br>'+(v.tool==='grille'?L('Lưu lượng tổng nhóm','Group total flow')+': '+F(v.x.flow)+' m³/h · '+L('Diện tích hữu dụng / mặt','Free / face area')+': '+F(v.x.free)+'%':L('Hệ số K mỗi phụ kiện','K per fitting')+': '+F(v.x.k,4)+' · ΣK: '+F(v.r.kTotal,4)+' · ρ: '+F(v.r.rho,3)+' kg/m³'+(v.x.medium==='water'?' · '+F(v.x.temp)+' °C':'')+'<br>'+L('Nguồn K / điều kiện','K source / conditions')+': '+E(v.x.source))+'</p>').join('');}
