const main=document.querySelector('main'),section=document.createElement('section');section.className='panel segment-list item-schedule';section.innerHTML='<div class="panel-title"><h2>'+titles[key]+'</h2><div class="report-buttons"><button type="button" data-item-preview>'+L('Xem báo cáo','View report')+'</button><button type="button" data-item-print>'+L('Xuất PDF','Export PDF')+'</button></div></div><p class="field-help">'+L('Lưu vào dự án đang chọn. Kết quả giữ nguyên lúc lưu; sửa để tính và cập nhật lại. Tối đa 300 mục mỗi công cụ.','Save to the selected project. Results remain as saved; edit to recalculate and update. Up to 300 items per tool.')+'</p><div class="segment-editor"><label>'+L('Tên / mã','Name / code')+'<input data-item-name maxlength="100" placeholder="'+(key==='insulation'?'INS-01':key==='grille'?'SA-D01':'EL-01')+'"></label><label>'+L(key!=='fittings'?'Phòng / khu vực (tùy chọn)':'Tuyến nối tiếp / đường dòng',key!=='fittings'?'Room / zone (optional)':'Series path / flow path')+'<input data-item-zone maxlength="100" placeholder="'+(key==='grille'?L('Văn phòng tầng 1','Level 1 office'):'SA-01')+'"></label><button type="button" data-item-add>'+L('Thêm vào danh sách','Add to schedule')+'</button><button type="button" data-item-cancel hidden>'+L('Hủy sửa','Cancel edit')+'</button></div><p class="field-help" data-item-message role="status"></p>'+(key==='fittings'?'<label class="item-route-label">'+L('Xem tuyến','View path')+'<select data-item-route></select></label><div data-item-total role="status"></div>':'')+'<div data-item-table></div><p class="field-help">'+scope[key]+'</p>';
