function refresh(){const all=items(),p=window.HVACProjects?.current();if(editing&&p?.id!==editingProject){editing=null;editingProject=null;get('name').value='';get('zone').value='';message('');}let filtered=all;if(key==='fittings'){const groups=paths(all);if(!groups.some(g=>g.id===route))route='';get('route').innerHTML='<option value="">'+L('Tất cả tuyến — không cộng tổng','All paths — no combined total')+'</option>'+groups.map(g=>'<option value="'+E(g.id)+'">'+E(g.zone)+' · '+L(g.medium==='water'?'Nước':'Gió',g.medium==='water'?'Water':'Air')+'</option>').join('');get('route').value=route;const group=groups.find(g=>g.id===route);if(group)filtered=group.items;get('total').innerHTML=group?'<p class="calc-note"><strong>'+L('Tổng phụ kiện tuyến đã chọn','Selected path fitting total')+': '+F(group.total)+' Pa'+(group.medium==='water'?' / '+F(group.total/1000,4)+' kPa':'')+'</strong></p>':'';}
get('table').innerHTML=filtered.length?table(filtered,true):'<p class="field-help">'+L('Chưa có kết quả đã lưu.','No saved results yet.')+'</p>';get('add').textContent=editing?L('Cập nhật mục','Update item'):L('Thêm vào danh sách','Add to schedule');get('cancel').hidden=!editing;get('preview').disabled=get('print').disabled=!filtered.length;}
